using LaboratoryDesktopApp.DemoData;
using LaboratoryDesktopApp.Models;
using LaboratoryDesktopApp.Theme;

namespace LaboratoryDesktopApp.Controls;

public class TestEditorForm : Form
{
    private readonly LabTest? original; private readonly TextBox name=ThemeHelper.TextBox(), code=ThemeHelper.TextBox(), description=ThemeHelper.TextBox(), sample=ThemeHelper.TextBox(), price=ThemeHelper.TextBox(), hours=ThemeHelper.TextBox(); private readonly ComboBox category=new(); private readonly CheckBox active=new(){Text="Active",Checked=true,AutoSize=true}; private readonly DataGridView parameters=new(); private readonly List<TestParameter> parameterList=new();
    public TestEditorForm(LabTest? test)
    {
        original=test; Text=test==null?"Add Test":"Edit Test"; StartPosition=FormStartPosition.CenterParent; Size=new Size(820,760); MinimumSize=new Size(760,650); BackColor=AppTheme.Background; Font=AppTheme.Body; parameterList=test?.Parameters.Select(Clone).ToList()??new();
        var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(24),ColumnCount=2,RowCount=7,BackColor=AppTheme.Background}; root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50)); root.RowStyles.Add(new RowStyle(SizeType.Absolute,42));root.RowStyles.Add(new RowStyle(SizeType.Absolute,70));root.RowStyles.Add(new RowStyle(SizeType.Absolute,70));root.RowStyles.Add(new RowStyle(SizeType.Absolute,70));root.RowStyles.Add(new RowStyle(SizeType.Absolute,70));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,54)); root.Controls.Add(new Label{Text=test==null?"Add a laboratory test":"Edit laboratory test",Font=AppTheme.PageTitle,Dock=DockStyle.Fill},0,0);root.SetColumnSpan(root.GetControlFromPosition(0,0)!,2);
        AddField(root,"Test Name *",name,0,1);AddField(root,"Test Code *",code,1,1); category.DropDownStyle=ComboBoxStyle.DropDownList;category.Items.AddRange(DemoDataProvider.Categories.Where(c=>c.IsActive).Select(c=>c.Name).ToArray());if(category.Items.Count==0)category.Items.Add("General");category.SelectedIndex=0;if(test!=null&&category.Items.Contains(test.Category))category.SelectedItem=test.Category;AddField(root,"Test Category *",category,0,2);AddField(root,"Sample Type *",sample,1,2);AddField(root,"Demo Price *",price,0,3);AddField(root,"Turnaround Time (hours) *",hours,1,3);AddField(root,"Description",description,0,4);root.Controls.Add(active,1,4);
        var paramPanel=new Panel{Dock=DockStyle.Fill,BackColor=AppTheme.Surface,Padding=new Padding(8)};ThemeHelper.StyleGrid(parameters);parameters.Dock=DockStyle.Fill;parameters.Columns.Add("Name","Parameter");parameters.Columns.Add("Code","Code");parameters.Columns.Add("Type","Result Type");parameters.Columns.Add("Unit","Unit");parameters.Columns.Add("Status","Status");paramPanel.Controls.Add(parameters);var paramButtons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=44};var add=ThemeHelper.Button("Add Parameter",true);var edit=ThemeHelper.Button("Edit Parameter");var remove=ThemeHelper.Button("Remove");add.Click+=(_,_)=>ParameterDialog(null);edit.Click+=(_,_)=>{if(parameters.CurrentRow!=null)ParameterDialog(parameterList[parameters.CurrentRow.Index]);};remove.Click+=(_,_)=>{if(parameters.CurrentRow!=null){parameterList.RemoveAt(parameters.CurrentRow.Index);RefreshParameters();}};paramButtons.Controls.AddRange(new Control[]{add,edit,remove});paramPanel.Controls.Add(paramButtons);root.Controls.Add(paramPanel,0,5);root.SetColumnSpan(paramPanel,2);
        var footer=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};var save=ThemeHelper.Button("Save Test",true);var cancel=ThemeHelper.Button("Cancel");save.Click+=(_,_)=>SaveTest();cancel.Click+=(_,_)=>{DialogResult=DialogResult.Cancel;Close();};footer.Controls.Add(save);footer.Controls.Add(cancel);root.Controls.Add(footer,0,6);root.SetColumnSpan(footer,2);Controls.Add(root);
        if(test!=null){name.Text=test.Name;code.Text=test.Code;sample.Text=test.SampleType;price.Text=test.Price.ToString();hours.Text=test.TurnaroundHours.ToString();description.Text=test.Description;active.Checked=test.IsActive;} RefreshParameters();
    }
    private void AddField(TableLayoutPanel p,string label,Control c,int col,int row){var box=new Panel{Dock=DockStyle.Fill};box.Controls.Add(ThemeHelper.Label(label));c.Location=new Point(4,24);c.Width=col==0?350:350;c.Anchor=AnchorStyles.Left|AnchorStyles.Right|AnchorStyles.Top;box.Controls.Add(c);box.Resize+=(_,_)=>c.Width=box.ClientSize.Width-10;p.Controls.Add(box,col,row);}
    private void RefreshParameters(){parameters.Rows.Clear();foreach(var p in parameterList)parameters.Rows.Add(p.Name,p.Code,p.DataType,p.Unit,p.IsActive?"Active":"Inactive");}
    private void ParameterDialog(TestParameter? item){using var f=new TestParameterForm(item);if(f.ShowDialog(this)==DialogResult.OK&&f.Result!=null){if(item==null)parameterList.Add(f.Result);else{var i=parameterList.IndexOf(item);parameterList[i]=f.Result;}RefreshParameters();}}
    private void SaveTest(){if(string.IsNullOrWhiteSpace(name.Text)||string.IsNullOrWhiteSpace(code.Text)||string.IsNullOrWhiteSpace(sample.Text)||category.SelectedItem==null){MessageBox.Show("Complete all required fields.","Validation",MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}if(DemoDataProvider.Tests.Any(t=>t.Code.Equals(code.Text.Trim(),StringComparison.OrdinalIgnoreCase)&&t.Id!=original?.Id)){MessageBox.Show("Test code already exists.","Validation",MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}if(!decimal.TryParse(price.Text,out var p)||p<0){MessageBox.Show("Enter a valid non-negative demo price.","Validation",MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}if(!int.TryParse(hours.Text,out var h)||h<1){MessageBox.Show("Turnaround time must be a positive whole number of hours.","Validation",MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}if(original==null){var t=new LabTest();CopyTo(t,p,h);DemoDataProvider.Tests.Add(t);}else CopyTo(original,p,h);MessageBox.Show("Demo test updated in memory. It will not persist after closing the app.","Saved",MessageBoxButtons.OK,MessageBoxIcon.Information);DialogResult=DialogResult.OK;Close();}
    private void CopyTo(LabTest t,decimal p,int h){t.Name=name.Text.Trim();t.Code=code.Text.Trim();t.Category=category.Text;t.SampleType=sample.Text.Trim();t.Price=p;t.TurnaroundHours=h;t.Description=description.Text.Trim();t.IsActive=active.Checked;t.Parameters=parameterList.Select(Clone).ToList();}
    private static TestParameter Clone(TestParameter p)=>new(){Id=p.Id,Name=p.Name,Code=p.Code,DataType=p.DataType,Unit=p.Unit,ReferenceInfo=p.ReferenceInfo,IsRequired=p.IsRequired,DisplayOrder=p.DisplayOrder,IsActive=p.IsActive};
}
